export type Cell = [number, number];

const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  x === otherX && y === otherY;

const isNeighbor = (cell: Cell, other: Cell): boolean =>
  !isSameCell(cell, other) &&
  Math.abs(cell[0] - other[0]) <= 1 &&
  Math.abs(cell[1] - other[1]) <= 1;

const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((other) => isNeighbor(cell, other)).length;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => countLiveNeighbors(cell, liveCells) === 2);
}

